# Check 8v^3 - u^3 = 5 for |u| <= 5, |v| <= 5
solutions_5 = []
for u in range(-5, 6):
    for v in range(-5, 6):
        if 8 * (v**3) - (u**3) == 5:
            solutions_5.append((u, v))

print("Solutions for 8v^3 - u^3 = 5:")
print(solutions_5)

